// 线段树更新操作：插入一张价格为 q 的票
function change(x, l, r, q) {
    if (l === r) {
        num[x]++;
        t[x] += l;
        return;
    }
    const mid = Math.floor((l + r) / 2);
    if (q <= mid) {
        change(x * 2, l, mid, q);
    } else {
        change(x * 2 + 1, mid + 1, r, q);
    }
    // 更新当前节点信息
    t[x] = t[x * 2] + t[x * 2 + 1];
    num[x] = num[x * 2] + num[x * 2 + 1];
}
