// 查询线段树中价格最小的 q 张票的总费用
function query(x, l, r, q) {
    if (l === r) {
        return BigInt(l) * BigInt(q);
    }
    const mid = Math.floor((l + r) / 2);
    if (q === num[x * 2]) {
        return BigInt(t[x * 2]);
    }
    if (q > num[x * 2]) {
        return BigInt(t[x * 2]) + query(x * 2 + 1, mid + 1, r, q - num[x * 2]);
    } else {
        return query(x * 2, l, mid, q);
    }
}
