// 读取输入
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let n = 0;
const inputLines = [];
​
rl.on('line', (line) => {
    inputLines.push(line.trim());
    if (inputLines.length === 1) {
        n = parseInt(line.trim());
    } else if (inputLines.length === n + 1) {
        rl.close();
    }
});
