rl.on('close', () => {
    let max_a = 0, max_b = 1;
    let result = BigInt(0);
​
    // 输入处理
    for (let i = 1; i <= n; ++i) {
        const [xStr, yStr] = inputLines[i].split(' ');
        const x = parseInt(xStr), y = parseInt(yStr);
        max_a = Math.max(max_a, x);
        if (y === 0) continue;
        max_b = Math.max(max_b, y);
        result += BigInt(y);
        tree1[x].push(y);
    }
​
    // 对每个候选人的支持票价进行排序，并按位置填入 f[]
    for (let i = 1; i <= max_a; ++i) {
        if (tree1[i].length > 0) {
            tree1[i].sort((a, b) => b - a); // 降序
            for (let j = 0; j < tree1[i].length; ++j) {
                f[j + 1].push(tree1[i][j]);
            }
        }
    }
    // 初始拥有k张票
    let k = n;
    // 花费代表所有所有的和
    let tmp = result;
    // 允许其它候选人有i张票
    for (let i = 1; i <= n; ++i) {
        // 更新手中的票
        k -= f[i].length;
        // 释放票 更新代价
        for (const price of f[i]) {
            change(1, 1, max_b, price);
            tmp -= BigInt(price);
        }
        let add = BigInt(0);
        // 释放完票之后手头不足i+1张票 需要进行回购
        if (k <= i) {
            add = query(1, 1, max_b, Math.min(i + 1 - k, n));
        }
        result = result < tmp + add ? result : tmp + add;
    }
​
    console.log(result.toString());
});
