package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
const (
    MAXN = 100005
    MAXB = 400005
)
​
var (
    tree1 [MAXN][]int         // tree1[i]：支持候选人 i 的所有票价
    f     [MAXN][]int         // f[i]：每个候选人第 i 张便宜的票集合
    num   [MAXB * 4]int       // 线段树：num[i] 表示区间内票的数量
    t     [MAXB * 4]int64     // 线段树：t[i] 表示区间内票的总价格
)
​
// 线段树更新操作：插入一张价格为 q 的票
func change(x, l, r, q int) {
    if l == r {
        num[x]++
        t[x] += int64(l)
        return
    }
    mid := (l + r) / 2
    if q <= mid {
        change(x*2, l, mid, q)
    } else {
        change(x*2+1, mid+1, r, q)
    }
    // 更新当前节点信息
    t[x] = t[x*2] + t[x*2+1]
    num[x] = num[x*2] + num[x*2+1]
}
​
// 查询线段树中价格最小的 q 张票的总费用
func query(x, l, r, q int) int64 {
    if l == r {
        return int64(l) * int64(q)
    }
    mid := (l + r) / 2
    if q == num[x*2] {
        return t[x*2]
    }
    if q > num[x*2] {
        return t[x*2] + query(x*2+1, mid+1, r, q-num[x*2])
    }
    return query(x*2, l, mid, q)
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    n, _ := strconv.Atoi(strings.TrimSpace(line))
​
    maxA := 0
    maxB := 1
    var result int64 = 0
​
    // 输入处理
    for i := 0; i < n; i++ {
        line, _ = reader.ReadString('\n')
        parts := strings.Fields(line)
        x, _ := strconv.Atoi(parts[0])
        y, _ := strconv.Atoi(parts[1])
        // 最大候选人数
        if x > maxA {
            maxA = x
        }
        if y == 0 {
            continue
        }
        // 最大值
        if y > maxB {
            maxB = y
        }
        result += int64(y)
        tree1[x] = append(tree1[x], y)
    }
​
    // 对每个候选人的支持票价进行排序，并按位置填入 f[]
    for i := 1; i <= maxA; i++ {
        if len(tree1[i]) > 0 {
            sort.Slice(tree1[i], func(a, b int) bool {
                return tree1[i][a] > tree1[i][b] // 降序
            })
            for j, price := range tree1[i] {
                f[j+1] = append(f[j+1], price)
            }
        }
    }
​
    // 初始我拥有所有票
    k := n
    // 初始我拥有所有票的花费
    tmp := result
​
    // 允许其它候选人有 i 张票
    for i := 1; i <= n; i++ {
        // 手中余票减少的数量
        k -= len(f[i])
        for _, price := range f[i] {
            // 释放这些票
            change(1, 1, maxB, price)
            // 减少的花费
            tmp -= int64(price)
        }
        var add int64 = 0
        // 让所有人可以拥有 i 张票的情况下,我手头的票可能不足 i + 1,我需要再购买一些回来
        if k <= i {
            add = query(1, 1, maxB, min(i+1-k, n))
        }
        if tmp+add < result {
            result = tmp + add
        }
    }
​
    fmt.Println(result)
}
